const IDIOMAS = { br: TEXTOS_BR, mg: TEXTOS_MG, en: TEXTOS_EN };
const ROTULOS_IDIOMA = { br: "PT-BR", mg: "PT-MG", en: "EN" };

// as fotos do Chico
const CHICO_FELIZ    = "data:image/png;base64,";

const CHICO_TAMPANDO = "data:image/png;base64,";


const pegar = id => document.getElementById(id);
console.log("AgendaUai login — versão 7 carregada");


/* IDIOMA: guarda a escolha, senão vai de mineiro */
let idiomaAtual = "mg";
let telaAtual = "login";   // qual tela tá aberta
try {
  const salvo = localStorage.getItem("idioma");
  if (IDIOMAS[salvo]) idiomaAtual = salvo;
  else if ((navigator.language || "").toLowerCase().startsWith("en")) idiomaAtual = "en";
} catch (e) {}

// pega o texto na língua certa, se faltar vai de br
function t(chave) {
  return IDIOMAS[idiomaAtual][chave] ?? TEXTOS_BR[chave] ?? chave;
}

// traduz tudo que é texto fixo
function traduzirTextos() {
  document.documentElement.lang = (idiomaAtual === "en") ? "en" : "pt-BR";

  document.querySelectorAll("[data-i18n]").forEach(el => { el.textContent = t(el.dataset.i18n); });
  document.querySelectorAll("[data-i18n-ph]").forEach(el => { el.placeholder = t(el.dataset.i18nPh); });
  document.querySelectorAll("[data-i18n-title]").forEach(el => {
    el.title = t(el.dataset.i18nTitle);
    el.setAttribute("aria-label", t(el.dataset.i18nTitle));
  });

  // o que depende do momento
  pegar("ver").textContent  = (pegar("senha").type  === "password") ? t("mostrar") : t("ocultar");
  pegar("verC").textContent = (pegar("senhaC").type === "password") ? t("mostrar") : t("ocultar");
  document.querySelectorAll("#codigo input").forEach((q, i) => q.setAttribute("aria-label", t("digito") + " " + (i + 1)));
  pegar("Chico").alt = t("altChico");
  document.title = t({ login: "tituloLogin", cadastro: "tituloCadastro", redefinir: "tituloRedefinir" }[telaAtual]) + " — AgendaUai";

  // botão e menu do idioma
  pegar("rotuloIdioma").textContent = ROTULOS_IDIOMA[idiomaAtual];
  document.querySelectorAll("#menuIdioma [data-idioma]").forEach(b => {
    b.setAttribute("aria-checked", b.dataset.idioma === idiomaAtual);
  });
}

// trocou de língua limpa os avisos velhos
function limparMensagens() {
  document.querySelectorAll(".msg").forEach(m => { m.textContent = ""; m.dataset.fixa = ""; });
  document.querySelectorAll("input.erro, fieldset.erro").forEach(c => c.classList.remove("erro"));
  document.querySelectorAll("#regras li").forEach(li => li.classList.remove("falha"));
}

function mudarIdioma(novo) {
  idiomaAtual = novo;
  try { localStorage.setItem("idioma", novo); } catch (e) {}
  traduzirTextos();
  limparMensagens();
}

// menu do idioma
(function iniciarMenuDeIdioma() {
  const botao = pegar("btnIdioma"), menu = pegar("menuIdioma");
  const abrirFechar = abrir => { menu.hidden = !abrir; botao.setAttribute("aria-expanded", abrir); };

  botao.addEventListener("click", e => { e.stopPropagation(); abrirFechar(menu.hidden); });
  menu.querySelectorAll("[data-idioma]").forEach(item => {
    item.addEventListener("click", () => { mudarIdioma(item.dataset.idioma); abrirFechar(false); });
  });
  document.addEventListener("click", () => abrirFechar(false));          // clicou fora, fecha
  document.addEventListener("keydown", e => { if (e.key === "Escape") abrirFechar(false); });
})();


/* MODO CLARO E ESCURO */
(function iniciarTema() {
  const raiz = document.documentElement;
  let temaAtual = null;
  try { temaAtual = localStorage.getItem("tema"); } catch (e) {}
  if (!temaAtual) temaAtual = matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
  raiz.setAttribute("data-tema", temaAtual);

  pegar("tema").addEventListener("click", () => {
    temaAtual = (temaAtual === "dark") ? "light" : "dark";
    raiz.setAttribute("data-tema", temaAtual);
    try { localStorage.setItem("tema", temaAtual); } catch (e) {}
  });
})();


/* CHICO: feliz, mas tampa o olho na senha */
const chico = pegar("Chico");
chico.src = CHICO_FELIZ;
[CHICO_FELIZ, CHICO_TAMPANDO].forEach(src => { new Image().src = src; });
chico.dataset.atual = CHICO_FELIZ;

function mudarChico(novaImagem) {
  if (chico.dataset.atual === novaImagem) return;
  chico.dataset.atual = novaImagem;
  chico.classList.add("troca");
  setTimeout(() => { chico.src = novaImagem; chico.classList.remove("troca"); }, 200);
}

document.querySelectorAll('input[type="password"], input[data-senha]').forEach(campo => {
  campo.addEventListener("focus", () => { if (campo.type === "password") mudarChico(CHICO_TAMPANDO); });
  campo.addEventListener("blur", () => mudarChico(CHICO_FELIZ));
});

// Mostrar e Ocultar do login
pegar("ver").onclick = () => {
  const campo = pegar("senha");
  const estavaOculta = (campo.type === "password");
  campo.type = estavaOculta ? "text" : "password";
  campo.setAttribute("data-senha", "1");
  pegar("ver").textContent = estavaOculta ? t("ocultar") : t("mostrar");
  mudarChico(estavaOculta ? CHICO_FELIZ : CHICO_TAMPANDO);
  campo.focus();
};


/* CONFERINDO O EMAIL */
function checarEmail(texto) {
  const email = texto.trim().toLowerCase();
  if (!/^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/.test(email)) return t("emailInvalido");

  return "";
}

// mostra o aviso ou limpa, devolve true se deu ruim
function mostrarErro(campo, caixaMensagem, texto) {
  caixaMensagem.textContent = texto;
  caixaMensagem.className = "msg";
  caixaMensagem.dataset.fixa = "";
  campo.classList.toggle("erro", texto !== "");
  return texto !== "";
}

// aviso verdinho, deu bão
function mostrarOk(caixaMensagem, texto) {
  caixaMensagem.className = "msg ok";
  caixaMensagem.textContent = texto;
}

// aviso com link, o fixa segura o aviso pro blur não apagar
function mostrarErroComLink(campo, caixaMensagem, html) {
  caixaMensagem.className = "msg";
  caixaMensagem.innerHTML = html;
  caixaMensagem.dataset.fixa = "1";
  campo.classList.add("erro");
}

function limparErroAoDigitar(campo, caixaMensagem) {
  campo.addEventListener("input", () => {
    campo.classList.remove("erro");
    caixaMensagem.textContent = "";
    caixaMensagem.dataset.fixa = "";
  });
}

function avisarEmailAoSair(campo, caixaMensagem) {
  campo.addEventListener("blur", () => {
    if (caixaMensagem.dataset.fixa === "1") return;
    if (campo.value.trim() !== "") mostrarErro(campo, caixaMensagem, checarEmail(campo.value));
  });
}


/* Para a demonstração, a senha precisa ter apenas 6 caracteres ou mais. */
function checarSenhaForte(senha) {
  return senha.length < 6 ? t("senhaMin6") : "";
}


/* Autenticação de demonstração armazenada no navegador. */
const authApi = window.AgendaUaiApi;
const campoEmail = pegar("email"), campoSenha = pegar("senha");
const msgEmail = pegar("msgEmail"), msgSenha = pegar("msgSenha");
const campoNome = pegar("nome"), campoEmailC = pegar("emailC");
const campoSenhaC = pegar("senhaC"), campoSenhaC2 = pegar("senhaC2");
const msgTipo = pegar("msgTipo"), msgNome = pegar("msgNome"), msgEmailC = pegar("msgEmailC");
const msgSenhaC = pegar("msgSenhaC"), msgSenhaC2 = pegar("msgSenhaC2");
const campoEmailR = pegar("emailR"), msgEmailR = pegar("msgEmailR"), msgCodigo = pegar("msgCodigo");
const quadradinhos = Array.from(document.querySelectorAll("#codigo input"));
const radiosTipo = document.querySelectorAll('input[name="tipoConta"]');

function destinoDoTipo(tipo) {
  return tipo === "prestador"
    ? "../cadastrar-lojas/cadastrar-lojas.html"
    : "../home/index.html";
}

function destinoSeguro() {
  const value = new URLSearchParams(window.location.search).get("returnTo");
  if (!value) return "";
  try {
    const target = new URL(value, window.location.href);
    return target.origin === window.location.origin ? target.href : "";
  } catch {
    return "";
  }
}

async function redirecionarDepoisDoLogin(user) {
  const requested = destinoSeguro();
  if (requested) {
    window.location.href = requested;
    return;
  }
  const role = user.user_metadata?.tipo_conta;
  if (role === "prestador") {
    const store = await authApi.getStore();
    window.location.href = store
      ? "../painel%20do%20profissional/index.html"
      : destinoDoTipo("prestador");
    return;
  }
  const store = await authApi.getStore();
  if (store?.profissional_id === user.id) {
    window.location.href = "../painel%20do%20profissional/index.html";
    return;
  }
  window.location.href = destinoDoTipo("contratante");
}

function tipoEscolhido() {
  return document.querySelector('input[name="tipoConta"]:checked')?.value || "";
}

function mostrarTela(tela) {
  const formularios = {
    login: pegar("f"),
    cadastro: pegar("fc"),
    redefinir: pegar("fr")
  };
  const formularioAtivo = formularios[tela];
  if (!formularioAtivo) return;

  telaAtual = tela;
  Object.values(formularios).forEach(formulario => {
    formulario.hidden = formulario !== formularioAtivo;
  });
  pegar("cartao").classList.toggle("sem-chico", tela === "redefinir");
  limparMensagens();

  if (tela === "redefinir") comecarRedefinicaoDoZero();
  traduzirTextos();

  const primeiroCampo = formularioAtivo.querySelector(
    'input:not([type="checkbox"]):not([type="radio"]):not([hidden])'
  );
  primeiroCampo?.focus({ preventScroll: true });
}

function mensagemModoArquivo() {
  return "Abra o site pelo GitHub Pages ou por um servidor web local para carregar o catálogo JSON.";
}

function comecarRedefinicaoDoZero() {
  if (pegar("etapaEmail")) pegar("etapaEmail").hidden = false;
  if (pegar("etapaCodigo")) pegar("etapaCodigo").hidden = true;
  if (pegar("subRedefinir")) {
    pegar("subRedefinir").textContent = "Digite o e-mail da sua conta para gerar um código local de redefinição.";
  }
  if (msgEmailR) msgEmailR.textContent = "";
  if (msgCodigo) msgCodigo.textContent = "";
}

function mostrarFormularioNovaSenha() {
  const step = pegar("etapaCodigo");
  if (!step) return;
  pegar("etapaEmail").hidden = true;
  step.hidden = false;
  const codeFields = pegar("codigo");
  if (codeFields) codeFields.hidden = true;
  quadradinhos.forEach(input => input.hidden = true);
  pegar("subRedefinir").textContent = "Escolha uma nova senha para sua conta.";
  let form = pegar("form-nova-senha");
  if (!form) {
    form = document.createElement("div");
    form.id = "form-nova-senha";
    form.innerHTML = '<label for="codigoRedefinicao">Código de redefinição</label><input id="codigoRedefinicao" inputmode="numeric" autocomplete="one-time-code"><label for="novaSenha">Nova senha</label><input id="novaSenha" type="password" autocomplete="new-password"><label for="novaSenhaConfirmacao">Repita a nova senha</label><input id="novaSenhaConfirmacao" type="password" autocomplete="new-password"><p class="msg" id="msgNovaSenha" role="status"></p>';
    step.prepend(form);
  }
  pegar("btnCodigo").textContent = "Salvar nova senha";
  pegar("btnCodigo").onclick = async () => {
    const password = pegar("novaSenha").value;
    const confirmation = pegar("novaSenhaConfirmacao").value;
    const message = pegar("msgNovaSenha");
    if (password.length < 6 || password !== confirmation) {
      message.textContent = password.length < 6
        ? "A senha deve ter pelo menos 6 caracteres."
        : "As senhas não conferem.";
      return;
    }
    try {
      const { error } = await authApi.getClient().auth.updateUser({ password }, { code: pegar("codigoRedefinicao").value.trim(), resetToken: sessionStorage.getItem("agendauai:reset-token") });
      if (error) throw error;
      sessionStorage.removeItem("agendauai:reset-token");
      message.textContent = "Senha atualizada. Você já pode entrar com a nova senha.";
      setTimeout(() => window.location.href = "login1510.html", 1200);
    } catch (error) {
      message.textContent = error.message || "Não foi possível atualizar sua senha.";
    }
  };
}

limparErroAoDigitar(campoEmail, msgEmail);
limparErroAoDigitar(campoSenha, msgSenha);
avisarEmailAoSair(campoEmail, msgEmail);
pegar("ver").onclick = () => {
  const hidden = campoSenha.type === "password";
  campoSenha.type = hidden ? "text" : "password";
  pegar("ver").textContent = hidden ? t("ocultar") : t("mostrar");
};

pegar("f").addEventListener("submit", async evento => {
  evento.preventDefault();
  if (mostrarErro(campoEmail, msgEmail, checarEmail(campoEmail.value))) return;
  if (mostrarErro(campoSenha, msgSenha, campoSenha.value.length < 6 ? t("senhaMin6") : "")) return;
  if (window.location.protocol === "file:") {
    mostrarErro(campoSenha, msgSenha, mensagemModoArquivo());
    return;
  }
  const button = pegar("btn");
  button.disabled = true;
  try {
    const { data, error } = await authApi.getClient().auth.signInWithPassword({
      email: campoEmail.value.trim(),
      password: campoSenha.value
    });
    if (error) throw error;
    mostrarOk(msgSenha, t("loginOk"));
    await redirecionarDepoisDoLogin(data.user);
  } catch (error) {
      mostrarErroComLink(campoSenha, msgSenha,
      /invalid login credentials|invalid email or password/i.test(error.message)
        ? t("senhaErrada")
        : error.message || "Não foi possível entrar. Confira o e-mail e a senha desta demonstração neste navegador.");
  } finally {
    button.disabled = false;
  }
});

limparErroAoDigitar(campoNome, msgNome);
limparErroAoDigitar(campoEmailC, msgEmailC);
limparErroAoDigitar(campoSenhaC, msgSenhaC);
limparErroAoDigitar(campoSenhaC2, msgSenhaC2);
avisarEmailAoSair(campoEmailC, msgEmailC);
radiosTipo.forEach(radio => radio.addEventListener("change", () => {
  pegar("tipoConta").classList.remove("erro");
  msgTipo.textContent = "";
}));
pegar("verC").onclick = () => {
  const hidden = campoSenhaC.type === "password";
  [campoSenhaC, campoSenhaC2].forEach(input => input.type = hidden ? "text" : "password");
  pegar("verC").textContent = hidden ? t("ocultar") : t("mostrar");
};

pegar("fc").addEventListener("submit", async evento => {
  evento.preventDefault();
  const role = tipoEscolhido();
  const consent = document.querySelector('input[name="aceite"]');
  const errors = [
    mostrarErro(pegar("tipoConta"), msgTipo, role ? "" : t("escolherTipo")),
    mostrarErro(campoNome, msgNome, campoNome.value.trim().length < 3 ? t("nomeCurto") : ""),
    mostrarErro(campoEmailC, msgEmailC, checarEmail(campoEmailC.value)),
    mostrarErro(campoSenhaC, msgSenhaC, checarSenhaForte(campoSenhaC.value)),
    mostrarErro(campoSenhaC2, msgSenhaC2, campoSenhaC2.value !== campoSenhaC.value ? t("senhasDiferentes") : "")
  ];
  if (errors.includes(true)) return;
  if (consent && !consent.checked) {
    mostrarErro(campoEmailC, msgEmailC, "Aceite os Termos de Uso e a Política de Privacidade para continuar.");
    return;
  }
  if (window.location.protocol === "file:") {
    mostrarErro(campoEmailC, msgEmailC, mensagemModoArquivo());
    return;
  }

  const button = pegar("fc").querySelector('button[type="submit"]');
  button.disabled = true;
  try {
    const { data, error } = await authApi.getClient().auth.signUp({
      email: campoEmailC.value.trim(),
      password: campoSenhaC.value,
      options: {
        data: {
          nome_completo: campoNome.value.trim(),
          tipo_conta: role
        }
      }
    });
    if (error) throw error;
    if (!data.session) {
      mostrarOk(msgSenhaC2, "Conta criada. Confira seu e-mail e confirme o cadastro antes de entrar.");
      return;
    }
    mostrarOk(msgSenhaC2, t("cadastroOk"));
    await redirecionarDepoisDoLogin(data.user);
  } catch (error) {
    const message = /email rate limit exceeded|over_email_send_rate_limit/i.test(error.message)
      ? t("limiteEmail")
      : /already registered|already exists/i.test(error.message)
        ? t("jaCadastrado")
        : error.message || "Não foi possível criar a conta neste navegador. Confira os dados e o espaço disponível.";
    mostrarErroComLink(campoEmailC, msgEmailC, message);
  } finally {
    button.disabled = false;
  }
});

limparErroAoDigitar(campoEmailR, msgEmailR);
avisarEmailAoSair(campoEmailR, msgEmailR);
pegar("fr").addEventListener("submit", async evento => {
  evento.preventDefault();
  if (mostrarErro(campoEmailR, msgEmailR, checarEmail(campoEmailR.value))) return;
  if (window.location.protocol === "file:") {
    mostrarErro(campoEmailR, msgEmailR, mensagemModoArquivo());
    return;
  }
  try {
    const redirectTo = new URL(window.location.href);
    redirectTo.searchParams.set("modo", "redefinir");
    redirectTo.searchParams.delete("returnTo");
    redirectTo.hash = "";
    const { data, error } = await authApi.getClient().auth.resetPasswordForEmail(
      campoEmailR.value.trim(), { redirectTo: redirectTo.href }
    );
    if (error) throw error;
    if (data?.demoCode) {
      mostrarOk(msgEmailR, `Código de demonstração: ${data.demoCode}. Use-o para definir uma nova senha.`);
      mostrarFormularioNovaSenha();
    } else mostrarOk(msgEmailR, "Se este e-mail estiver cadastrado, você receberá as instruções de redefinição.");
  } catch (error) {
    const message = /email rate limit exceeded|over_email_send_rate_limit/i.test(error.message)
      ? t("limiteEmail")
      : error.message || "Não foi possível enviar o link de redefinição.";
    mostrarErro(campoEmailR, msgEmailR, message);
  }
});

pegar("btnCodigo").addEventListener("click", () => {
  msgCodigo.textContent = "Informe o código de demonstração exibido após a solicitação para criar uma nova senha.";
});

try {
  authApi.getClient().auth.onAuthStateChange(event => {
    if (event === "PASSWORD_RECOVERY") mostrarFormularioNovaSenha();
  });
} catch (error) {
  console.info("O login local da demonstração está ativo.");
}

// Links entre as telas de login, cadastro e redefinição.
document.addEventListener("click", evento => {
  const link = evento.target.closest("[data-ir]");
  if (!link) return;
  evento.preventDefault();
  if (link.dataset.ir === "redefinir") {
    const email = !pegar("f").hidden ? campoEmail.value : !pegar("fc").hidden ? campoEmailC.value : "";
    if (email) campoEmailR.value = email;
  }
  mostrarTela(link.dataset.ir);
});

const mode = new URLSearchParams(window.location.search).get("modo");
if (mode === "cadastro") mostrarTela("cadastro");
if (mode === "redefinir") mostrarTela("redefinir");
traduzirTextos();
